"""Generate src/qcref/_keys.py: typed attribute declarations for every data key.

Each collection class inherits from a generated `*Keys` class whose annotation-only
attributes (`Ni: Element`) let type checkers and IDEs see the keys stored in the
CSV files. Annotations create nothing at runtime.

Run after changing data:  python build_tools/gen_keys.py
"""

from __future__ import annotations

import importlib
import sys
import types
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "src"
OUTPUT = SRC / "qcref" / "_keys.py"

HEADER = '''\
# Auto-generated by build_tools/gen_keys.py from the CSV data - DO NOT EDIT BY HAND
"""Typed declarations of every data key, for type checkers and IDEs."""

from __future__ import annotations

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from .constants import CodataCollection
    from .models import Value
    from .periodic_table import Element
    from .solvents import Solvent
'''


def _keys_class(name: str, keys: list[str], type_name: str) -> str:
    body = "".join(f"    {key}: {type_name}\n" for key in keys)
    return f"\n\nclass {name}:\n{body}"


KEY_CLASSES = ("ConstantKeys", "CodataKeys", "PeriodicTableKeys", "SolventKeys")


def render() -> str:
    if "qcref" not in sys.modules:
        # Load the package against placeholder key classes so generation never
        # depends on the (possibly stale or broken) file it is about to replace.
        sys.path.insert(0, str(SRC))
        placeholder = types.ModuleType("qcref._keys")
        for name in KEY_CLASSES:
            setattr(placeholder, name, type(name, (), {}))
        sys.modules["qcref._keys"] = placeholder
    constants = importlib.import_module("qcref.constants")
    periodic_table = importlib.import_module("qcref.periodic_table").periodic_table
    solvents = importlib.import_module("qcref.solvents").solvents

    curated = list(constants.constants)
    releases = [f"codata{year}" for year in constants.codata]
    module_names = "".join(f"{key}: Value\n" for key in curated) + "".join(
        f"{name}: CodataCollection\n" for name in releases
    )
    return (
        HEADER
        + "\n__all__ = [\n"
        + "".join(f'    "{name}",\n' for name in [*curated, *releases])
        + "]\n\n"
        + "# Module-level names of qcref.constants\n"
        + module_names
        + _keys_class("ConstantKeys", curated, "Value")
        + "".join(f"    {name}: CodataCollection\n" for name in releases)
        + _keys_class("CodataKeys", list(constants.phys), "Value")
        + _keys_class("PeriodicTableKeys", list(periodic_table), "Element")
        + _keys_class("SolventKeys", list(solvents), "Solvent")
    )


if __name__ == "__main__":
    OUTPUT.write_text(render(), encoding="utf-8")
    print(f"Wrote {OUTPUT.relative_to(ROOT)}")
